effect.shader:
// S_WipePixelate - wipe with pixel-block dissolve edge

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
    vec2 uv = acScreenNorm;

    // --- Build wipe direction from angle ---
    float ang = radians(angle);
    vec2 dir = vec2(cos(ang), sin(ang));

    // --- Pixel block grid ---
    // Frequency = number of blocks across; Chunky enlarges blocks.
    float freq = pixelFrequency / (1.0 + chunky * 4.0);
    vec2 cells = vec2(freq / max(pixelRelWidth, 0.001), freq);
    vec2 block = floor(uv * cells);
    vec2 blockCenter = (block + 0.5) / cells;

    // Per-block random value (seeded)
    float rnd = hash(block + vec2(seed * 1000.0));

    // --- Wipe coordinate measured at the block center ---
    float coord = dot(blockCenter - 0.5, dir) + 0.5;

    // Edge band: each block flips at a slightly different point,
    // scattered by its random value across edgeWidth -> pixel dissolve.
    float ew = max(edgeWidth, 0.0001);
    float threshold = coord + (rnd - 0.5) * ew;

    // wipePercent 0 -> fully present, 1 -> fully wiped
    float wiped = step(threshold, wipePercent); // 1 = block removed

    // Direction handling
    float reveal;
    if (transitionDir == 0) {       // Wipe Off to Bg
        reveal = 1.0 - wiped;       // 1 = show source
    } else {                        // Wipe On from Bg
        reveal = wiped;             // source appears as wipe grows
    }

    // --- Show Wipe matte preview ---
    if (showWipe > 0.5) {
        gl_FragColor = vec4(vec3(reveal), 1.0);
        return;
    }

    // --- Composite source over chosen background ---
    vec4 src = texture2DCv(inputImg.texture, uv);

    vec4 bg;
    if (background == 1) {
        bg = vec4(0.0, 0.0, 0.0, 1.0);   // Black
    } else {
        bg = vec4(0.0, 0.0, 0.0, 0.0);   // None / transparent
    }

    // Premultiplied-safe blend of source vs background by reveal mask
    vec4 outCol = mix(bg, src, reveal);

    gl_FragColor = outCol;
}
